begin;
create function pg_temp.listing_claim(uid uuid) returns void language plpgsql as $$begin perform set_config('request.jwt.claims',jsonb_build_object('sub',uid,'role','authenticated','aal','aal1')::text,true);end$$;
create function pg_temp.listing_assert(ok boolean,label text) returns void language plpgsql as $$begin if ok is distinct from true then raise exception 'LISTING DELETE ASSERT: %',label;end if;end$$;
insert into auth.users(id,email,email_confirmed_at) values('96000000-0000-4000-8000-000000000001','listing-owner@example.invalid',now()),('96000000-0000-4000-8000-000000000002','listing-buyer@example.invalid',now());
do $$declare owner_id uuid:='96000000-0000-4000-8000-000000000001';buyer uuid:='96000000-0000-4000-8000-000000000002';sid uuid;fixed_id uuid;auction_id uuid;reserved_id uuid;photo text;result jsonb;oid uuid;begin
 perform pg_temp.listing_claim(owner_id);perform public.th_api('snapshot');perform pg_temp.listing_claim(buyer);perform public.th_api('snapshot');select id into sid from public.th_shops where user_id=owner_id;update public.th_shops set status='verified' where id=sid;
 photo:=owner_id::text||'/96000000-0000-4000-8000-000000000099.png';insert into public.th_uploads(path,user_id) values(photo,owner_id);
 insert into public.th_products(shop_id,title,description,category,condition,location,image_path,price,mode) values(sid,'Fixed deletion fixture','Product removal regression','home','สภาพดี','Bangkok',photo,100,'fixed') returning id into fixed_id;
 insert into public.th_products(shop_id,title,description,category,condition,location,image_path,price,mode,bid_step,ends_at) values(sid,'Auction one click deletion','Product removal regression','home','สภาพดี','Bangkok',photo,100,'auction',10,public.th_now()+3600000) returning id into auction_id;
 perform public.th_api('bid',jsonb_build_object('productId',auction_id,'amount',110,'requestKey','listing-delete-bid-01'));
 insert into public.th_cart values(buyer,fixed_id);insert into public.th_favorites values(buyer,fixed_id);
 begin perform public.th_api('product_delete',jsonb_build_object('productId',fixed_id));raise exception 'Foreign deletion accepted';exception when sqlstate 'PT404' then null;end;
 perform pg_temp.listing_claim(owner_id);result:=public.th_api('product_delete',jsonb_build_object('productId',fixed_id));
 perform pg_temp.listing_assert(not exists(select 1 from jsonb_array_elements(result->'products')x where x->>'id'=fixed_id::text),'fixed removed from own and public catalog');
 perform pg_temp.listing_assert((select listing_deleted_at is not null from public.th_products where id=fixed_id),'fixed data retained');
 perform pg_temp.listing_assert(not exists(select 1 from public.th_cart where product_id=fixed_id) and not exists(select 1 from public.th_favorites where product_id=fixed_id),'cart and favorites cleaned');
 perform public.th_api('product_delete',jsonb_build_object('productId',fixed_id));perform pg_temp.listing_assert((select count(*) from public.th_events where action='product_delete' and subject=fixed_id::text)=1,'idempotent delete');
 result:=public.th_api('product_delete',jsonb_build_object('productId',auction_id));perform pg_temp.listing_assert((select status='withdrawn' and auction_cancelled_at is not null and listing_deleted_at is not null from public.th_products where id=auction_id),'one action cancels and removes auction with bids');
 perform pg_temp.listing_assert((select count(*) from public.th_bids where product_id=auction_id)=1,'bids preserved');
 perform pg_temp.listing_claim(buyer);result:=public.th_api('snapshot');perform pg_temp.listing_assert(result#>>array['bids',auction_id::text,'status']='cancelled','bidder sees cancellation');
 begin perform public.th_api('bid',jsonb_build_object('productId',auction_id,'amount',120,'requestKey','listing-delete-bid-02'));raise exception 'Deleted auction accepted bid';exception when sqlstate 'PT409' then null;end;
 insert into public.th_products(shop_id,title,description,category,condition,location,image_path,price,mode) values(sid,'Reserved item','Product removal regression','home','สภาพดี','Bangkok',photo,100,'fixed') returning id into reserved_id;
 result:=public.th_api('reserve',jsonb_build_object('productIds',jsonb_build_array(reserved_id),'requestKey','listing-delete-reserve','delivery','pickup'));oid:=(result->>'orderId')::uuid;
 perform pg_temp.listing_claim(owner_id);begin perform public.th_api('product_delete',jsonb_build_object('productId',reserved_id));raise exception 'Reserved deletion accepted';exception when sqlstate 'PT409' then null;end;
 perform pg_temp.listing_assert((select listing_deleted_at is null and reserved_order_id=oid from public.th_products where id=reserved_id),'existing order preserved');
 perform set_config('request.jwt.claims','{}',true);begin perform public.th_api('product_delete',jsonb_build_object('productId',fixed_id));raise exception 'Anonymous deletion accepted';exception when sqlstate 'PT401' then null;end;
end$$;
select 'Unified fixed/auction deletion, bid retention, ownership and order protection: PASS' as result;
rollback;
